/* ============================================================================
   Locate - Fusion des articles en double. Idempotent.

   180 articles en double (même désignation, marque et modèle, au pluriel, aux accents,
   aux espaces et aux mots « de », « type », « à »… près) sont fusionnés dans l'article conservé :
   le plus utilisé du groupe. Leurs biens (Immo) et lignes de commande sont rattachés à l'article
   conservé, qui reprend la catégorie du doublon s'il n'en avait pas ; puis le doublon est supprimé.

   Sauvegardes (créées une fois) : dbo._Sauvegarde_ArticleDoublon (articles supprimés),
   dbo._Sauvegarde_ImmoArticle et dbo._Sauvegarde_CommandeLigneArticle (anciens rattachements).
   ============================================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Fusion TABLE (IdGarde bigint NOT NULL, IdDoublon bigint NOT NULL PRIMARY KEY);

/* Seulement les paires encore présentes (le script peut être rejoué) */
DELETE f FROM @Fusion f
WHERE NOT EXISTS (SELECT 1 FROM dbo.Article a WHERE a.Id = f.IdDoublon)
   OR NOT EXISTS (SELECT 1 FROM dbo.Article a WHERE a.Id = f.IdGarde);

IF OBJECT_ID('dbo._Sauvegarde_ArticleDoublon') IS NULL
    SELECT TOP 0 a.*, CAST(0 AS bigint) AS IdGarde, GETDATE() AS DateFusion INTO dbo._Sauvegarde_ArticleDoublon FROM dbo.Article a;
IF OBJECT_ID('dbo._Sauvegarde_ImmoArticle') IS NULL
    CREATE TABLE dbo._Sauvegarde_ImmoArticle (IdImmo bigint NOT NULL, IdArticleAvant bigint NOT NULL, IdArticleApres bigint NOT NULL, DateFusion datetime NOT NULL DEFAULT GETDATE());
IF OBJECT_ID('dbo._Sauvegarde_CommandeLigneArticle') IS NULL
    CREATE TABLE dbo._Sauvegarde_CommandeLigneArticle (IdLigne bigint NOT NULL, IdArticleAvant bigint NOT NULL, IdArticleApres bigint NOT NULL, DateFusion datetime NOT NULL DEFAULT GETDATE());

BEGIN TRAN;


UPDATE i SET i.IdArticle = f.IdGarde FROM dbo.Immo i INNER JOIN @Fusion f ON f.IdDoublon = i.IdArticle;
UPDATE l SET l.IdArticle = f.IdGarde FROM dbo.CommandeAchatLigne l INNER JOIN @Fusion f ON f.IdDoublon = l.IdArticle;

/* L'article conservé reprend la catégorie d'un doublon s'il n'en avait pas */
DECLARE @Categorie TABLE (IdGarde bigint PRIMARY KEY, IdCategorie bigint);
UPDATE a SET a.IdCategorie = c.IdCategorie FROM dbo.Article a INNER JOIN @Categorie c ON c.IdGarde = a.Id
WHERE a.IdCategorie IS NULL AND EXISTS (SELECT 1 FROM dbo.Categorie x WHERE x.Id = c.IdCategorie);

DELETE a FROM dbo.Article a INNER JOIN @Fusion f ON f.IdDoublon = a.Id;

COMMIT TRAN;

SELECT (SELECT COUNT(*) FROM dbo._Sauvegarde_ArticleDoublon) AS ArticlesFusionnes,
       (SELECT COUNT(*) FROM dbo._Sauvegarde_ImmoArticle) AS BiensRattaches,
       (SELECT COUNT(*) FROM dbo.Article) AS ArticlesRestants;
PRINT 'Fusion des articles en double terminée.';
