INSERT INTO dbo._Sauvegarde_ArticleDoublon SELECT a.*, f.IdGarde, GETDATE() FROM dbo.Article a INNER JOIN @Fusion f ON f.IdDoublon = a.Id;
INSERT INTO dbo._Sauvegarde_ImmoArticle (IdImmo, IdArticleAvant, IdArticleApres) SELECT i.Id, i.IdArticle, f.IdGarde FROM dbo.Immo i INNER JOIN @Fusion f ON f.IdDoublon = i.IdArticle;
INSERT INTO dbo._Sauvegarde_CommandeLigneArticle (IdLigne, IdArticleAvant, IdArticleApres) SELECT l.Id, l.IdArticle, f.IdGarde FROM dbo.CommandeAchatLigne l INNER JOIN @Fusion f ON f.IdDoublon = l.IdArticle;
